-- composition of rule kernels build_side_probe_side x filter_pushdown (duckdb), template not_exists
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT ARRAY['x'::text, NULL::text] AS c0, 10.0::float8 AS c1, (SELECT MIN ('-1 month'::interval) FROM t0 AS a3) AS c2 FROM t3 AS a1 WHERE (SELECT BOOL_AND (TRUE) FROM t4 AS a2) UNION ALL SELECT ARRAY['1'::text] AS c0, 0.0::float8 AS c1, '00:00:00.000001'::interval AS c2) AS ka WHERE NOT EXISTS (SELECT 1 FROM (SELECT '2024-01-01'::date AS c0, (MAX ('1999-12-31 23:59:59.999999+05:30'::timestamptz) OVER (PARTITION BY '2000-01-01 00:00:00+00'::timestamptz) + '00:00:00.000001'::interval) AS c1 FROM t1 AS a1 WHERE NULLIF ((NULL::int < 2), FALSE)) AS kb);
-- pgfuzz:check kernel:not_exists SELECT CASE WHEN (SELECT count(*) FROM (SELECT '2024-01-01'::date AS c0, (MAX ('1999-12-31 23:59:59.999999+05:30'::timestamptz) OVER (PARTITION BY '2000-01-01 00:00:00+00'::timestamptz) + '00:00:00.000001'::interval) AS c1 FROM t1 AS a1 WHERE NULLIF ((NULL::int < 2), FALSE)) AS kb) = 0 THEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT ARRAY['x'::text, NULL::text] AS c0, 10.0::float8 AS c1, (SELECT MIN ('-1 month'::interval) FROM t0 AS a3) AS c2 FROM t3 AS a1 WHERE (SELECT BOOL_AND (TRUE) FROM t4 AS a2) UNION ALL SELECT ARRAY['1'::text] AS c0, 0.0::float8 AS c1, '00:00:00.000001'::interval AS c2) AS ka) ELSE 0 END
